# The Apptegy family (edjobs::fetch_apptegy_postings(), edjobs 0.18.0, 2026-11-14;
# claude-notes/2026-11-14_apptegy-family/): each registry row, with its own Job_Link, City, Platform (mode) and
# k12_list_rules.csv rule, against the district's captured page(s). Expected titles are the routine's output,
# checked line by line against each district's old parser (parity.R; every difference listed in the README).
# Test titles name the parser and the district so the auto-fix issue finds that district's fixtures.
# Generated by claude-notes/2026-11-14_apptegy-family/make_family_test.R.

apptegy_parse <- function(district, fixture) {
  reg <- read.csv(here::here("k12_district_registry.csv"), stringsAsFactors = FALSE)
  row <- reg[reg$District == district, ]
  expect_equal(nrow(row), 1)
  rules <- read_k12_list_rules(here::here("k12_list_rules.csv"))
  content <- paste(readLines(fixture, warn = FALSE, encoding = "UTF-8"), collapse = "\n")
  r <- parse_apptegy_postings(content, row$Job_Link, row$City, APPTEGY_FAMILY_MODES[[row$Platform]],
                              k12_list_rule(rules, district, "List_Start"), k12_list_rule(rules, district, "List_Stop"),
                              k12_list_rule(rules, district, "Skip_Section"))
  expect_true(all(r$Location == row$City))
  expect_true(all(r$Link == row$Job_Link))
  r
}

test_that("parse_apptegy_postings: Wolf Point Public Schools", {
  r <- apptegy_parse("Wolf Point Public Schools", test_path("fixtures", "apptegy_wolfpoint_rendered.txt"))
