test_that("the family and the bespoke map cover every Apptegy-session registry row once, each with a spec", {
  reg <- read.csv(here::here("k12_district_registry.csv"), stringsAsFactors = FALSE)
  fam <- apptegy_family_scrapers(reg, read_k12_list_rules(here::here("k12_list_rules.csv")))
  expect_setequal(names(fam), reg$District[reg$Platform %in% c("Apptegy", "ApptegyPageBuilder")])
  expect_length(intersect(names(fam), names(APPTEGY_DISTRICT_SCRAPERS)), 0)
  for (d in names(fam)) expect_equal(edjobs::resolve_scraper_call(d)$fn, "fetch_apptegy_postings", info = d)
  expect_equal(edjobs::resolve_scraper_call("Conrad Public Schools")$args[[3]], "pagebuilder")
  expect_equal(edjobs::resolve_scraper_call("Plevna School District #55")$args[[4]],
               "^[0-9]{4}-[0-9]{4} School Year Positions Open:$")
})

test_that("k12_list_rules.csv: one row per family district, each rule a valid perl regex", {
  reg <- read.csv(here::here("k12_district_registry.csv"), stringsAsFactors = FALSE)
  rules <- read_k12_list_rules(here::here("k12_list_rules.csv"))
  expect_equal(names(rules), c("District", "List_Start", "List_Stop", "Skip_Section"))
  expect_false(anyDuplicated(rules$District) > 0)
  # Rules are read by the Apptegy and Google Sites family routines.
  expect_true(all(rules$District %in% reg$District[reg$Platform %in% c(names(APPTEGY_FAMILY_MODES), "GoogleSites")]))
  for (col in c("List_Start", "List_Stop", "Skip_Section")) for (rx in stats::na.omit(rules[[col]])) {
    expect_silent(grepl(rx, "x", perl = TRUE))
  }
  expect_true(is.na(k12_list_rule(rules, "Melstone Public Schools", "List_Start")))
})

test_that("fetch_apptegy_k12_postings runs the family through one session, each row tagged with its District", {
  reg <- read.csv(here::here("k12_district_registry.csv"), stringsAsFactors = FALSE)
  reg <- reg[reg$District %in% c("Melstone Public Schools", "Deer Lodge School District #1"), ]
  rd <- function(f) paste(readLines(test_path("fixtures", f), warn = FALSE, encoding = "UTF-8"), collapse = "\n")
  pages <- list(text = rd("apptegy_melstone_rendered.txt"), html = rd("deerlodge_apptegy_pagedata.html"))
  sessions <- 0; at <- NULL
  factory <- function() {
    sessions <<- sessions + 1
    list(Page = list(navigate = function(url) at <<- url, loadEventFired = function(...) invisible(NULL)),
         Runtime = list(evaluate = function(js) list(result = list(value =
           if (grepl("outerHTML", js)) pages$html else pages$text))),
         close = function() invisible(NULL))
  }
  local_mocked_bindings(Sys.sleep = function(...) NULL, .package = "base")
  r <- fetch_apptegy_k12_postings(factory, log_path = tempfile(), scrapers = apptegy_family_scrapers(reg, read_k12_list_rules(here::here("k12_list_rules.csv"))))
  expect_equal(sessions, 1)
  expect_equal(sum(r$District == "Melstone Public Schools"), 9)
  expect_equal(sum(r$District == "Deer Lodge School District #1"), 5)
  expect_true(all(r$Location[r$District == "Deer Lodge School District #1"] == "Deer Lodge"))
  expect_true(all(c("Pay_Min", "Pay_Text") %in% names(r)))
})
